    query.done = false;
  } else if (done !== null) {
    errors.push({ field: "done", message: "must be true or false" });
  }
  const q = params.get("q");
  if (q !== null) {
    query.q = q;
  }
  const sort = params.get("sort");
  if (sort === "oldest" || sort === "newest" || sort === "title") {
    query.sort = sort;
  } else if (sort !== null) {
    errors.push({ field: "sort", message: "must be oldest, newest or title" });
