}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? "/", "http://localhost");
  const id = todoId(url.pathname);

  if (req.method === "GET" && url.pathname === "/todos") {
    const query = listQueryFrom(url.searchParams);
    if (Array.isArray(query)) {
      sendError(res, { kind: "validation", fields: query });
      return;
    }
    send(res, 200, listTodos(query));
    return;
  }

  if (req.method === "POST" && url.pathname === "/todos") {
    const body = await readBody(req);
    const parsed = parseJson(body);
    if (!parsed.ok) {
      sendError(res, { kind: "invalid_json" });
      return;
    }
    const checked = createFrom(parsed.data);
    if (Array.isArray(checked)) {
      sendError(res, { kind: "validation", fields: checked });
      return;
    }
    const todo = addTodo(checked);
    send(res, 201, todo);
    return;
  }

  if (req.method === "GET" && id !== undefined) {
    const todo = findTodo(id);
    if (todo === undefined) {
      sendError(res, { kind: "not_found" });
      return;
    }
    send(res, 200, todo);
    return;
  }

  if (req.method === "PATCH" && id !== undefined) {
    const todo = findTodo(id);
    if (todo === undefined) {
      sendError(res, { kind: "not_found" });
      return;
    }
    const body = await readBody(req);
    const parsed = parseJson(body);
    if (!parsed.ok) {
      sendError(res, { kind: "invalid_json" });
      return;
    }
    const checked = changesFrom(parsed.data);
    if (Array.isArray(checked)) {
      sendError(res, { kind: "validation", fields: checked });
      return;
    }
    const updated = updateTodo(todo, checked);
    send(res, 200, updated);
    return;
  }

  if (req.method === "DELETE" && id !== undefined) {
    const removed = deleteTodo(id);
    if (!removed) {
      sendError(res, { kind: "not_found" });
      return;
    }
    sendEmpty(res, 204);
    return;
  }

  sendError(res, { kind: "not_found" });
}

type Parsed =
  | { ok: true; data: unknown }
  | { ok: false };

function parseJson(text: string): Parsed {
  try {
    return { ok: true, data: JSON.parse(text) };
  } catch {
    return { ok: false };
  }
}

async function handler(req: IncomingMessage, res: ServerResponse): Promise<void> {
  try {
    await route(req, res);
  } catch (err: unknown) {
    console.error(err);
    if (res.headersSent) {
      res.end();
      return;
    }
    sendError(res, { kind: "server_error" });
  }
}

// ---- request replayer (given — don't edit) --------------------------------
// stdin:  one request per line —  METHOD /path [json body]
// stdout: one line per request —  <status> <response body>
// Since module 16 it starts your server exactly as server.ts does, with no
// safety net: an error that escapes `handler` crashes the process.
const server = createServer(handler);
await new Promise<void>((ok) => server.listen(0, "127.0.0.1", () => ok()));
const addr = server.address();
const base = `http://127.0.0.1:${addr === null ? 0 : addr.port}`;
for (const line of readFileSync(0, "utf8").split("\n")) {
  const text = line.trim();
  if (!text) continue;
  const parts = text.split(" ");
  const method = parts[0] ?? "GET";
  const path = parts[1] ?? "/";
  const body = parts.slice(2).join(" ");
  const headers: Record<string, string> = {};
  if (body) headers["Content-Type"] = "application/json";
  const reply = await fetch(base + path, { method, headers, body: body || undefined });
  console.log(reply.status, (await reply.text()).trim());
}
server.close();

