      sendError(res, { kind: "not_found" });
      return;
    }
    const body = await readBody(req);
    const parsed = parseJson(body);
    if (!parsed.ok) {
      sendError(res, { kind: "invalid_json" });
      return;
    }
    const checked = changesFrom(parsed.data);
    if (Array.isArray(checked)) {
      sendError(res, { kind: "validation", fields: checked });
      return;
    }
    const updated = updateTodo(todo, checked);
    send(res, 200, updated);
    return;
  }

  if (req.method === "DELETE" && id !== undefined) {
    const removed = deleteTodo(id);
    if (!removed) {
      sendError(res, { kind: "not_found" });
      return;
    }
    sendEmpty(res, 204);
    return;
  }

  sendError(res, { kind: "not_found" });
}

type Parsed =
  | { ok: true; data: unknown }
  | { ok: false };

function parseJson(text: string): Parsed {
  try {
    return { ok: true, data: JSON.parse(text) };
  } catch {
    return { ok: false };
  }
}

type Saved = {
  nextId: number;
  todos: Todo[];
};

function todoFrom(value: unknown): Todo | undefined {
  const obj = objectFrom(value);
  if (obj === undefined || !("id" in obj) || !("title" in obj) || !("done" in obj)) {
    return undefined;
  }
  const id = obj.id;
  const title = titleFrom(obj.title);
  if (typeof id !== "number" || !Number.isInteger(id) || id < 1) {
    return undefined;
  }
  if (typeof title !== "string" || typeof obj.done !== "boolean") {
    return undefined;
  }
  return { id: id, title: title, done: obj.done };
}

function savedFrom(data: unknown): Saved | undefined {
  const obj = objectFrom(data);
  if (obj === undefined || !("nextId" in obj) || !("todos" in obj)) {
    return undefined;
  }
  const next = obj.nextId;
  if (typeof next !== "number" || !Number.isInteger(next) || next < 1 || !Array.isArray(obj.todos)) {
    return undefined;
  }
  const items: unknown[] = obj.todos;
  const loaded: Todo[] = [];
  let lastId = 0;
  for (const item of items) {
    const todo = todoFrom(item);
    if (todo === undefined || todo.id <= lastId || todo.id >= next) {
      return undefined;
    }
    loaded.push(todo);
    lastId = todo.id;
  }
  return { nextId: next, todos: loaded };
}

function loadStore(): void {
  if (!existsSync(DATA_FILE)) {
    return;
  }
  const parsed = parseJson(readFileSync(DATA_FILE, "utf8"));
  if (!parsed.ok) {
    throw new Error(DATA_FILE + " is not JSON");
  }
  const saved = savedFrom(parsed.data);
  if (saved === undefined) {
    throw new Error(DATA_FILE + " is not a saved todo list");
  }
  todos.push(...saved.todos);
  nextId = saved.nextId;
}

async function handler(req: IncomingMessage, res: ServerResponse): Promise<void> {
  try {
    await route(req, res);
  } catch (err: unknown) {
    console.error(err);
    if (res.headersSent) {
      res.end();
      return;
    }
    sendError(res, { kind: "server_error" });
  }
}

// ---- request replayer (given — don't edit) --------------------------------
// stdin:  optionally first, `FILE <text>` — what todos.json holds before boot
//         (no FILE line: there is no file, as on a first-ever start). Then one
//         request per line —  METHOD /path [json body]
// stdout: one line per request —  <status> <response body> — and last,
//         `FILE <text>`: what todos.json holds afterwards.
// It boots as server.ts does — loadStore(), then createServer(handler) — and
// reports a loadStore that throws as `boot refused: <message>`.
const script = readFileSync(0, "utf8").split("\n");
const head = (script[0] ?? "").trim();
if (head.startsWith("FILE ")) {
  writeFileSync(DATA_FILE, head.slice(5));
  script.shift();
} else {
  rmSync(DATA_FILE, { force: true });
}
let booted = false;
try {
  loadStore();
  booted = true;
} catch (err: unknown) {
  console.log("boot refused:", err instanceof Error ? err.message : String(err));
}
if (booted) {
  const server = createServer(handler);
  await new Promise<void>((ok) => server.listen(0, "127.0.0.1", () => ok()));
  const addr = server.address();
  const base = `http://127.0.0.1:${addr === null ? 0 : addr.port}`;
  for (const line of script) {
    const text = line.trim();
    if (!text) continue;
    const parts = text.split(" ");
    const method = parts[0] ?? "GET";
    const path = parts[1] ?? "/";
    const body = parts.slice(2).join(" ");
    const headers: Record<string, string> = {};
    if (body) headers["Content-Type"] = "application/json";
    const reply = await fetch(base + path, { method, headers, body: body || undefined });
    console.log(reply.status, (await reply.text()).trim());
  }
  server.close();
}
console.log("FILE", existsSync(DATA_FILE) ? readFileSync(DATA_FILE, "utf8") : "(none)");

