  if (typeof next !== "number" || !Number.isInteger(next) || next < 1 || !Array.isArray(obj.todos)) {
    return undefined;
  }
  const items: unknown[] = obj.todos;
  const loaded: Todo[] = [];
  let lastId = 0;
  for (const item of items) {
    const todo = todoFrom(item);
    if (todo === undefined || todo.id <= lastId || todo.id >= next) {
