  const t = peek(p);
  if (t.kind === "op" && t.op === "-") {
    advance(p);
    const operand = parseUnary(p);           // itself: --3 is -(-3)
    if (!operand.ok) { return operand; }
    return { ok: true, expr: neg(operand.expr) };
