function isLetter(ch: string): boolean {
  return LETTERS.indexOf(ch) !== -1;
}

function scan(src: string): ScanResult {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src.charAt(i);
    if (ch === " ") {
      i = i + 1;
    } else if (isDigit(ch)) {
      const start = i;
      while (i < src.length && isDigit(src.charAt(i))) {
        i = i + 1;
      }
      const text = src.slice(start, i);
      tokens.push(numberToken(Number(text)));
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/") {
      tokens.push(opToken(ch));
      i = i + 1;
    } else if (ch === "(") {
      tokens.push(lparenToken());
      i = i + 1;
    } else if (ch === ")") {
      tokens.push(rparenToken());
