import { readFileSync } from "node:fs";

type Op = "+" | "-" | "*" | "/" | "<" | ">" | "==";

type NumberToken = { kind: "number"; value: number };
type BoolToken = { kind: "bool"; value: boolean };
type OpToken = { kind: "op"; op: Op };
type IdentToken = { kind: "ident"; name: string };
type LetToken = { kind: "let" };
type EqualsToken = { kind: "equals" };
type SemiToken = { kind: "semi" };
type LParenToken = { kind: "lparen" };
type RParenToken = { kind: "rparen" };
type EofToken = { kind: "eof" };

type Token =
  | NumberToken
  | BoolToken
  | OpToken
  | IdentToken
  | LetToken
  | EqualsToken
  | SemiToken
  | LParenToken
  | RParenToken
  | EofToken;

function numberToken(value: number): NumberToken {
  return { kind: "number", value: value };
}

function boolToken(value: boolean): BoolToken {
  return { kind: "bool", value: value };
}

function opToken(op: Op): OpToken {
  return { kind: "op", op: op };
}

function identToken(name: string): IdentToken {
  return { kind: "ident", name: name };
}

function letToken(): LetToken {
  return { kind: "let" };
}

function equalsToken(): EqualsToken {
  return { kind: "equals" };
}

function semiToken(): SemiToken {
  return { kind: "semi" };
}

function lparenToken(): LParenToken {
  return { kind: "lparen" };
}

function rparenToken(): RParenToken {
  return { kind: "rparen" };
}

function eofToken(): EofToken {
  return { kind: "eof" };
}

type Failure = { ok: false; error: string };
type ScanResult = { ok: true; tokens: Token[] } | Failure;

function unexpected(ch: string, i: number): string {
  return `error: unexpected '${ch}' at 1:${i + 1}`;
}

const DIGITS = "0123456789";

function isDigit(ch: string): boolean {
  return DIGITS.indexOf(ch) !== -1;
}

const LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_";

function isLetter(ch: string): boolean {
  return LETTERS.indexOf(ch) !== -1;
}

function scan(src: string): ScanResult {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src.charAt(i);
    if (ch === " ") {
      i = i + 1;
    } else if (isDigit(ch)) {
      const start = i;
      while (i < src.length && isDigit(src.charAt(i))) {
        i = i + 1;
      }
      const text = src.slice(start, i);
      tokens.push(numberToken(Number(text)));
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/" || ch === "<" || ch === ">") {
      tokens.push(opToken(ch));
      i = i + 1;
    } else if (ch === "(") {
      tokens.push(lparenToken());
      i = i + 1;
    } else if (ch === ")") {
      tokens.push(rparenToken());
      i = i + 1;
    } else if (isLetter(ch)) {
      const start = i;
      while (i < src.length && (isLetter(src.charAt(i)) || isDigit(src.charAt(i)))) {
        i = i + 1;
      }
      const word = src.slice(start, i);
      if (word === "let") {
        tokens.push(letToken());
      } else if (word === "true" || word === "false") {
        tokens.push(boolToken(word === "true"));
      } else {
        tokens.push(identToken(word));
      }
    } else if (ch === "=") {
      if (src.charAt(i + 1) === "=") {
        tokens.push(opToken("=="));
        i = i + 2;
      } else {
        tokens.push(equalsToken());
        i = i + 1;
      }
    } else if (ch === ";") {
      tokens.push(semiToken());
      i = i + 1;
    } else {
      return { ok: false, error: unexpected(ch, i) };
    }
  }
  tokens.push(eofToken());
  return { ok: true, tokens: tokens };
}

type NumLit = { kind: "num"; value: number };
type BoolLit = { kind: "bool"; value: boolean };
type Var = { kind: "var"; name: string };
type Neg = { kind: "neg"; operand: Expr };
type Binary = { kind: "binary"; op: Op; left: Expr; right: Expr };

type Expr = NumLit | BoolLit | Var | Neg | Binary;

function num(value: number): NumLit {
  return { kind: "num", value: value };
}

function boolLit(value: boolean): BoolLit {
  return { kind: "bool", value: value };
}

function variable(name: string): Var {
  return { kind: "var", name: name };
}

function neg(operand: Expr): Neg {
  return { kind: "neg", operand: operand };
}

function binary(op: Op, left: Expr, right: Expr): Binary {
  return { kind: "binary", op: op, left: left, right: right };
}

type LetStmt = { kind: "let"; name: string; value: Expr };
type ExprStmt = { kind: "expr"; expr: Expr };

type Stmt = LetStmt | ExprStmt;

type Parser = { tokens: Token[]; pos: number };

function peek(p: Parser): Token {
  const t = p.tokens[p.pos];
  if (t === undefined) {
    return eofToken();
  }
  return t;
}

function advance(p: Parser): Token {
  const t = peek(p);
  if (t.kind !== "eof") {
    p.pos = p.pos + 1;
  }
  return t;
}

function describe(t: Token): string {
  switch (t.kind) {
    case "number":
      return `'${t.value}'`;
    case "bool":
      return `'${t.value}'`;
    case "op":
      return `'${t.op}'`;
    case "ident":
      return `'${t.name}'`;
    case "let":
      return "'let'";
    case "equals":
      return "'='";
    case "semi":
      return "';'";
    case "lparen":
      return "'('";
    case "rparen":
      return "')'";
    case "eof":
      return "end of input";
    default: {
      const impossible: never = t;
      return impossible;
    }
  }
}

function unexpectedToken(t: Token): Failure {
  return { ok: false, error: `error: unexpected ${describe(t)}` };
}

function expected(what: string, t: Token): Failure {
  return { ok: false, error: `error: expected ${what} but found ${describe(t)}` };
}

type ParseResult = { ok: true; expr: Expr } | Failure;

function parseExpr(p: Parser): ParseResult {
  return parseComparison(p);
}

function parsePrimary(p: Parser): ParseResult {
  const t = advance(p);
  if (t.kind === "number") {
    return { ok: true, expr: num(t.value) };
  }
  if (t.kind === "bool") {
    return { ok: true, expr: boolLit(t.value) };
  }
  if (t.kind === "ident") {
    return { ok: true, expr: variable(t.name) };
  }
  if (t.kind === "lparen") {
    const inner = parseExpr(p);
    if (!inner.ok) {
      return inner;
    }
    const close = advance(p);
    if (close.kind !== "rparen") {
      return expected("')'", close);
    }
    return inner;
  }
  return unexpectedToken(t);
}

function parseUnary(p: Parser): ParseResult {
  const t = peek(p);
  if (t.kind === "op" && t.op === "-") {
    advance(p);
    const operand = parseUnary(p);
    if (!operand.ok) {
      return operand;
    }
    return { ok: true, expr: neg(operand.expr) };
  }
  return parsePrimary(p);
}

function parseProduct(p: Parser): ParseResult {
  const first = parseUnary(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "*" || t.op === "/")) {
    advance(p);
    const right = parseUnary(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseSum(p: Parser): ParseResult {
  const first = parseProduct(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "+" || t.op === "-")) {
    advance(p);
    const right = parseProduct(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseComparison(p: Parser): ParseResult {
  const first = parseSum(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "<" || t.op === ">" || t.op === "==")) {
    advance(p);
    const right = parseSum(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

type StmtResult = { ok: true; stmt: Stmt } | Failure;

function parseStatement(p: Parser): StmtResult {
  if (peek(p).kind !== "let") {
    const e = parseExpr(p);
    if (!e.ok) {
      return e;
    }
    return { ok: true, stmt: { kind: "expr", expr: e.expr } };
  }
  advance(p);
  const name = advance(p);
  if (name.kind !== "ident") {
    return expected("a name", name);
  }
  const eq = advance(p);
  if (eq.kind !== "equals") {
    return expected("'='", eq);
  }
  const value = parseExpr(p);
  if (!value.ok) {
    return value;
  }
  return { ok: true, stmt: { kind: "let", name: name.name, value: value.expr } };
}

type ProgramResult = { ok: true; program: Stmt[] } | Failure;

function parseProgram(tokens: Token[]): ProgramResult {
  const p: Parser = { tokens: tokens, pos: 0 };
  const program: Stmt[] = [];
  while (true) {
    const s = parseStatement(p);
    if (!s.ok) {
      return s;
    }
    program.push(s.stmt);
    const t = advance(p);
    if (t.kind === "eof") {
      return { ok: true, program: program };
    }
    if (t.kind !== "semi") {
      return unexpectedToken(t);
    }
    if (peek(p).kind === "eof") {
      return { ok: true, program: program };
    }
  }
}

type Value = number | boolean;

type EvalResult = { ok: true; value: Value } | Failure;

function checked(value: number): EvalResult {
  if (!Number.isFinite(value)) {
    return { ok: false, error: "error: number too large" };
  }
  return { ok: true, value: value };
}

type Env = Map<string, Value>;

function evaluate(e: Expr, env: Env): EvalResult {
  switch (e.kind) {
    case "num":
      return checked(e.value);
