  switch (t.kind) {
    case "number":
      return `'${t.value}'`;
    case "bool":
      return `'${t.value}'`;
    case "op":
      return `'${t.op}'`;
    case "ident":
      return `'${t.name}'`;
    case "let":
      return "'let'";
    case "equals":
      return "'='";
    case "semi":
      return "';'";
    case "lparen":
      return "'('";
    case "rparen":
      return "')'";
    case "eof":
      return "end of input";
    default: {
      const impossible: never = t;
      return impossible;
    }
  }
