function parseProduct(p: Parser): ParseResult {
  const first = parseUnary(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "*" || t.op === "/")) {
    advance(p);
    const right = parseUnary(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseSum(p: Parser): ParseResult {
  const first = parseProduct(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "+" || t.op === "-")) {
    advance(p);
    const right = parseProduct(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseComparison(p: Parser): ParseResult {
  const first = parseSum(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "<" || t.op === ">" || t.op === "==")) {
    advance(p);
    const right = parseSum(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

type StmtResult = { ok: true; stmt: Stmt } | Failure;

function parseStatement(p: Parser): StmtResult {
  if (peek(p).kind !== "let") {
    const e = parseExpr(p);
    if (!e.ok) {
      return e;
    }
    return { ok: true, stmt: { kind: "expr", expr: e.expr } };
  }
  advance(p);
  const name = advance(p);
  if (name.kind !== "ident") {
    return expected("a name", name);
  }
  const eq = advance(p);
  if (eq.kind !== "equals") {
    return expected("'='", eq);
  }
  const value = parseExpr(p);
  if (!value.ok) {
    return value;
  }
  return { ok: true, stmt: { kind: "let", name: name.name, value: value.expr } };
}

type ProgramResult = { ok: true; program: Stmt[] } | Failure;

function parseProgram(tokens: Token[]): ProgramResult {
  const p: Parser = { tokens: tokens, pos: 0 };
  const program: Stmt[] = [];
  while (true) {
    const s = parseStatement(p);
    if (!s.ok) {
      return s;
    }
    program.push(s.stmt);
    const t = advance(p);
    if (t.kind === "eof") {
      return { ok: true, program: program };
    }
    if (t.kind !== "semi") {
      return unexpectedToken(t);
    }
    if (peek(p).kind === "eof") {
      return { ok: true, program: program };
    }
  }
}

type Value = number | boolean;

type EvalResult = { ok: true; value: Value } | Failure;

function checked(value: number): EvalResult {
  if (!Number.isFinite(value)) {
    return { ok: false, error: "error: number too large" };
  }
  return { ok: true, value: value };
}

type Env = Map<string, Value>;

function evaluate(e: Expr, env: Env): EvalResult {
  switch (e.kind) {
    case "num":
      return checked(e.value);
    case "bool":
      return { ok: true, value: e.value };
    case "var": {
      const value = env.get(e.name);
      if (value === undefined) {
        return { ok: false, error: `error: undefined variable '${e.name}'` };
      }
      return { ok: true, value: value };
    }
    case "neg": {
      const operand = evaluate(e.operand, env);
      if (!operand.ok) {
        return operand;
      }
      if (typeof operand.value !== "number") {
        return { ok: false, error: "error: cannot apply '-' to a boolean" };
      }
      return { ok: true, value: -operand.value };
    }
    case "binary": {
      const left = evaluate(e.left, env);
      if (!left.ok) {
        return left;
      }
      const right = evaluate(e.right, env);
      if (!right.ok) {
        return right;
      }
      return apply(e.op, left.value, right.value);
    }
    case "if": {
      const cond = evaluate(e.cond, env);
      if (!cond.ok) {
        return cond;
      }
      if (typeof cond.value !== "boolean") {
        return { ok: false, error: "error: if condition must be a boolean" };
      }
      if (cond.value) {
        return evaluate(e.whenTrue, env);
      }
      return evaluate(e.whenFalse, env);
    }
    default: {
      const impossible: never = e;
      return impossible;
    }
  }
}

function apply(op: Op, left: Value, right: Value): EvalResult {
  if (op === "==") {
    if (typeof left !== typeof right) {
      return { ok: false, error: `error: cannot compare a ${typeof left} with a ${typeof right}` };
    }
    return { ok: true, value: left === right };
  }
  if (typeof left !== "number" || typeof right !== "number") {
    return { ok: false, error: `error: cannot apply '${op}' to a boolean` };
  }
  switch (op) {
    case "+":
      return checked(left + right);
    case "-":
      return checked(left - right);
    case "*":
      return checked(left * right);
    case "/":
      if (right === 0) {
        return { ok: false, error: "error: division by zero" };
      }
      return checked(left / right);
    case "<":
      return { ok: true, value: left < right };
    case ">":
      return { ok: true, value: left > right };
    default: {
      const impossible: never = op;
      return impossible;
    }
  }
}

function execute(s: Stmt, env: Env): EvalResult {
  switch (s.kind) {
    case "let": {
      const result = evaluate(s.value, env);
      if (!result.ok) {
        return result;
      }
      env.set(s.name, result.value);
      return result;
    }
    case "expr":
      return evaluate(s.expr, env);
    default: {
      const impossible: never = s;
      return impossible;
    }
  }
}

function runProgram(program: Stmt[], env: Env): EvalResult {
  let last: EvalResult = { ok: false, error: "error: empty program" };
  for (const s of program) {
    last = execute(s, env);
    if (!last.ok) {
      return last;
    }
  }
  return last;
}

function run(src: string, env: Env): string {
  const scanned = scan(src);
  if (!scanned.ok) {
    return scanned.error;
  }
  const parsed = parseProgram(scanned.tokens);
  if (!parsed.ok) {
    return parsed.error;
  }
  const result = runProgram(parsed.program, env);
  if (!result.ok) {
    return result.error;
  }
  return `${result.value}`;
}

const env: Env = new Map();
console.log(run(readFileSync(0, "utf8").trimEnd(), env));

exercises.solution:
import { readFileSync } from "node:fs";

type Op = "+" | "-" | "*" | "/" | "<" | ">" | "==";

type NumberToken = { kind: "number"; value: number };
type BoolToken = { kind: "bool"; value: boolean };
type OpToken = { kind: "op"; op: Op };
type IdentToken = { kind: "ident"; name: string };
type LetToken = { kind: "let" };
type EqualsToken = { kind: "equals" };
type SemiToken = { kind: "semi" };
type IfToken = { kind: "if" };
type ThenToken = { kind: "then" };
type ElseToken = { kind: "else" };
type LParenToken = { kind: "lparen" };
type RParenToken = { kind: "rparen" };
type EofToken = { kind: "eof" };

type Token =
  | NumberToken
  | BoolToken
  | OpToken
  | IdentToken
  | LetToken
  | EqualsToken
  | SemiToken
  | IfToken
  | ThenToken
  | ElseToken
  | LParenToken
  | RParenToken
  | EofToken;

function numberToken(value: number): NumberToken {
  return { kind: "number", value: value };
}

function boolToken(value: boolean): BoolToken {
  return { kind: "bool", value: value };
}

function opToken(op: Op): OpToken {
  return { kind: "op", op: op };
}

function identToken(name: string): IdentToken {
  return { kind: "ident", name: name };
}

function letToken(): LetToken {
  return { kind: "let" };
}

function equalsToken(): EqualsToken {
  return { kind: "equals" };
}

function semiToken(): SemiToken {
  return { kind: "semi" };
}

function ifToken(): IfToken {
  return { kind: "if" };
}

function thenToken(): ThenToken {
  return { kind: "then" };
}

function elseToken(): ElseToken {
  return { kind: "else" };
}

function lparenToken(): LParenToken {
  return { kind: "lparen" };
}

function rparenToken(): RParenToken {
  return { kind: "rparen" };
}

function eofToken(): EofToken {
  return { kind: "eof" };
}

type Failure = { ok: false; error: string };
type ScanResult = { ok: true; tokens: Token[] } | Failure;

function unexpected(ch: string, i: number): string {
  return `error: unexpected '${ch}' at 1:${i + 1}`;
}

const DIGITS = "0123456789";

function isDigit(ch: string): boolean {
  return DIGITS.indexOf(ch) !== -1;
}

const LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_";

function isLetter(ch: string): boolean {
  return LETTERS.indexOf(ch) !== -1;
}

function scan(src: string): ScanResult {
  const tokens: Token[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src.charAt(i);
    if (ch === " ") {
      i = i + 1;
    } else if (isDigit(ch)) {
      const start = i;
      while (i < src.length && isDigit(src.charAt(i))) {
        i = i + 1;
      }
      const text = src.slice(start, i);
      tokens.push(numberToken(Number(text)));
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/" || ch === "<" || ch === ">") {
      tokens.push(opToken(ch));
      i = i + 1;
    } else if (ch === "(") {
      tokens.push(lparenToken());
      i = i + 1;
    } else if (ch === ")") {
      tokens.push(rparenToken());
      i = i + 1;
    } else if (isLetter(ch)) {
      const start = i;
      while (i < src.length && (isLetter(src.charAt(i)) || isDigit(src.charAt(i)))) {
        i = i + 1;
      }
      const word = src.slice(start, i);
      if (word === "let") {
        tokens.push(letToken());
      } else if (word === "true" || word === "false") {
        tokens.push(boolToken(word === "true"));
      } else if (word === "if") {
        tokens.push(ifToken());
      } else if (word === "then") {
        tokens.push(thenToken());
      } else if (word === "else") {
        tokens.push(elseToken());
      } else {
        tokens.push(identToken(word));
      }
    } else if (ch === "=") {
      if (src.charAt(i + 1) === "=") {
        tokens.push(opToken("=="));
        i = i + 2;
      } else {
        tokens.push(equalsToken());
        i = i + 1;
      }
    } else if (ch === ";") {
      tokens.push(semiToken());
      i = i + 1;
    } else {
      return { ok: false, error: unexpected(ch, i) };
    }
  }
  tokens.push(eofToken());
  return { ok: true, tokens: tokens };
}

type NumLit = { kind: "num"; value: number };
type BoolLit = { kind: "bool"; value: boolean };
type Var = { kind: "var"; name: string };
type Neg = { kind: "neg"; operand: Expr };
type If = { kind: "if"; cond: Expr; whenTrue: Expr; whenFalse: Expr };
type Binary = { kind: "binary"; op: Op; left: Expr; right: Expr };

type Expr = NumLit | BoolLit | Var | Neg | If | Binary;

function num(value: number): NumLit {
  return { kind: "num", value: value };
}

function boolLit(value: boolean): BoolLit {
  return { kind: "bool", value: value };
}

function variable(name: string): Var {
  return { kind: "var", name: name };
}

function neg(operand: Expr): Neg {
  return { kind: "neg", operand: operand };
}

function ifExpr(cond: Expr, whenTrue: Expr, whenFalse: Expr): If {
  return { kind: "if", cond: cond, whenTrue: whenTrue, whenFalse: whenFalse };
}

function binary(op: Op, left: Expr, right: Expr): Binary {
  return { kind: "binary", op: op, left: left, right: right };
}

type LetStmt = { kind: "let"; name: string; value: Expr };
type ExprStmt = { kind: "expr"; expr: Expr };

type Stmt = LetStmt | ExprStmt;

type Parser = { tokens: Token[]; pos: number };

function peek(p: Parser): Token {
  const t = p.tokens[p.pos];
  if (t === undefined) {
    return eofToken();
  }
  return t;
}

function advance(p: Parser): Token {
  const t = peek(p);
  if (t.kind !== "eof") {
    p.pos = p.pos + 1;
  }
  return t;
}

function describe(t: Token): string {
  switch (t.kind) {
    case "number":
      return `'${t.value}'`;
    case "bool":
      return `'${t.value}'`;
    case "op":
      return `'${t.op}'`;
    case "ident":
      return `'${t.name}'`;
    case "let":
      return "'let'";
    case "equals":
      return "'='";
    case "semi":
      return "';'";
    case "if":
      return "'if'";
    case "then":
      return "'then'";
    case "else":
      return "'else'";
    case "lparen":
      return "'('";
    case "rparen":
      return "')'";
    case "eof":
      return "end of input";
    default: {
      const impossible: never = t;
      return impossible;
    }
  }
}

function unexpectedToken(t: Token): Failure {
  return { ok: false, error: `error: unexpected ${describe(t)}` };
}

function expected(what: string, t: Token): Failure {
  return { ok: false, error: `error: expected ${what} but found ${describe(t)}` };
}

type ParseResult = { ok: true; expr: Expr } | Failure;

function parseExpr(p: Parser): ParseResult {
  return parseComparison(p);
}

function parsePrimary(p: Parser): ParseResult {
  const t = advance(p);
  if (t.kind === "number") {
    return { ok: true, expr: num(t.value) };
  }
  if (t.kind === "bool") {
    return { ok: true, expr: boolLit(t.value) };
  }
  if (t.kind === "ident") {
    return { ok: true, expr: variable(t.name) };
  }
  if (t.kind === "lparen") {
    const inner = parseExpr(p);
    if (!inner.ok) {
      return inner;
    }
    const close = advance(p);
    if (close.kind !== "rparen") {
      return expected("')'", close);
    }
    return inner;
  }
  if (t.kind === "if") {
    const cond = parseExpr(p);
    if (!cond.ok) {
      return cond;
    }
    const thenTok = advance(p);
    if (thenTok.kind !== "then") {
      return expected("'then'", thenTok);
    }
    const whenTrue = parseExpr(p);
    if (!whenTrue.ok) {
      return whenTrue;
    }
    const elseTok = advance(p);
    if (elseTok.kind !== "else") {
      return expected("'else'", elseTok);
    }
    const whenFalse = parseExpr(p);
    if (!whenFalse.ok) {
      return whenFalse;
    }
    return { ok: true, expr: ifExpr(cond.expr, whenTrue.expr, whenFalse.expr) };
  }
  return unexpectedToken(t);
}

function parseUnary(p: Parser): ParseResult {
  const t = peek(p);
  if (t.kind === "op" && t.op === "-") {
    advance(p);
    const operand = parseUnary(p);
    if (!operand.ok) {
      return operand;
    }
    return { ok: true, expr: neg(operand.expr) };
  }
  return parsePrimary(p);
}

function parseProduct(p: Parser): ParseResult {
  const first = parseUnary(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "*" || t.op === "/")) {
    advance(p);
    const right = parseUnary(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseSum(p: Parser): ParseResult {
  const first = parseProduct(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "+" || t.op === "-")) {
    advance(p);
    const right = parseProduct(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseComparison(p: Parser): ParseResult {
  const first = parseSum(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "<" || t.op === ">" || t.op === "==")) {
    advance(p);
    const right = parseSum(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

type StmtResult = { ok: true; stmt: Stmt } | Failure;

function parseStatement(p: Parser): StmtResult {
  if (peek(p).kind !== "let") {
    const e = parseExpr(p);
    if (!e.ok) {
      return e;
    }
    return { ok: true, stmt: { kind: "expr", expr: e.expr } };
  }
  advance(p);
  const name = advance(p);
  if (name.kind !== "ident") {
    return expected("a name", name);
  }
  const eq = advance(p);
  if (eq.kind !== "equals") {
    return expected("'='", eq);
  }
  const value = parseExpr(p);
  if (!value.ok) {
    return value;
  }
  return { ok: true, stmt: { kind: "let", name: name.name, value: value.expr } };
}

type ProgramResult = { ok: true; program: Stmt[] } | Failure;

function parseProgram(tokens: Token[]): ProgramResult {
  const p: Parser = { tokens: tokens, pos: 0 };
  const program: Stmt[] = [];
  while (true) {
    const s = parseStatement(p);
    if (!s.ok) {
      return s;
    }
    program.push(s.stmt);
    const t = advance(p);
    if (t.kind === "eof") {
      return { ok: true, program: program };
    }
    if (t.kind !== "semi") {
      return unexpectedToken(t);
    }
    if (peek(p).kind === "eof") {
      return { ok: true, program: program };
    }
  }
}

type Value = number | boolean;

type EvalResult = { ok: true; value: Value } | Failure;

function checked(value: number): EvalResult {
  if (!Number.isFinite(value)) {
    return { ok: false, error: "error: number too large" };
  }
  return { ok: true, value: value };
}

type Env = Map<string, Value>;

function evaluate(e: Expr, env: Env): EvalResult {
  switch (e.kind) {
    case "num":
      return checked(e.value);
    case "bool":
      return { ok: true, value: e.value };
    case "var": {
      const value = env.get(e.name);
      if (value === undefined) {
        return { ok: false, error: `error: undefined variable '${e.name}'` };
      }
      return { ok: true, value: value };
    }
    case "neg": {
      const operand = evaluate(e.operand, env);
      if (!operand.ok) {
        return operand;
      }
      if (typeof operand.value !== "number") {
        return { ok: false, error: "error: cannot apply '-' to a boolean" };
      }
      return { ok: true, value: -operand.value };
    }
    case "binary": {
      const left = evaluate(e.left, env);
      if (!left.ok) {
        return left;
      }
      const right = evaluate(e.right, env);
      if (!right.ok) {
        return right;
      }
      return apply(e.op, left.value, right.value);
    }
    case "if": {
      const cond = evaluate(e.cond, env);
      if (!cond.ok) {
        return cond;
      }
      if (typeof cond.value !== "boolean") {
        return { ok: false, error: "error: if condition must be a boolean" };
      }
      if (cond.value) {
        return evaluate(e.whenTrue, env);
      }
      return evaluate(e.whenFalse, env);
    }
    default: {
      const impossible: never = e;
      return impossible;
    }
  }
}

function apply(op: Op, left: Value, right: Value): EvalResult {
  if (op === "==") {
    if (typeof left !== typeof right) {
      return { ok: false, error: `error: cannot compare a ${typeof left} with a ${typeof right}` };
    }
    return { ok: true, value: left === right };
  }
  if (typeof left !== "number" || typeof right !== "number") {
    return { ok: false, error: `error: cannot apply '${op}' to a boolean` };
  }
  switch (op) {
    case "+":
      return checked(left + right);
    case "-":
      return checked(left - right);
    case "*":
      return checked(left * right);
    case "/":
      if (right === 0) {
        return { ok: false, error: "error: division by zero" };
      }
      return checked(left / right);
    case "<":
      return { ok: true, value: left < right };
    case ">":
      return { ok: true, value: left > right };
    default: {
      const impossible: never = op;
      return impossible;
    }
  }
}

function execute(s: Stmt, env: Env): EvalResult {
  switch (s.kind) {
    case "let": {
      const result = evaluate(s.value, env);
      if (!result.ok) {
        return result;
      }
      env.set(s.name, result.value);
      return result;
    }
    case "expr":
      return evaluate(s.expr, env);
    default: {
      const impossible: never = s;
      return impossible;
    }
  }
}

function runProgram(program: Stmt[], env: Env): EvalResult {
  let last: EvalResult = { ok: false, error: "error: empty program" };
  for (const s of program) {
    last = execute(s, env);
    if (!last.ok) {
      return last;
    }
  }
  return last;
}

function run(src: string, env: Env): string {
  const scanned = scan(src);
  if (!scanned.ok) {
    return scanned.error;
  }
  const parsed = parseProgram(scanned.tokens);
  if (!parsed.ok) {
    return parsed.error;
  }
  const result = runProgram(parsed.program, env);
  if (!result.ok) {
    return result.error;
  }
  return `${result.value}`;
}

const env: Env = new Map();
console.log(run(readFileSync(0, "utf8").trimEnd(), env));

