    const ch = src.charAt(i);
    const pos: Pos = { line: line, col: i - lineStart + 1 };
    if (ch === "\n") {
      i = i + 1;
      line = line + 1;
      lineStart = i;
    } else if (ch === " " || ch === "\r") {
      i = i + 1;
    } else if (isDigit(ch)) {
      const start = i;
      while (i < src.length && isDigit(src.charAt(i))) {
        i = i + 1;
      }
      tokens.push(numberToken(Number(src.slice(start, i)), pos));
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/" || ch === "<" || ch === ">") {
      tokens.push(opToken(ch, pos));
      i = i + 1;
    } else if (ch === "(") {
      tokens.push(lparenToken(pos));
      i = i + 1;
    } else if (ch === ")") {
      tokens.push(rparenToken(pos));
      i = i + 1;
    } else if (isLetter(ch)) {
      const start = i;
      while (i < src.length && (isLetter(src.charAt(i)) || isDigit(src.charAt(i)))) {
        i = i + 1;
      }
      const word = src.slice(start, i);
      if (word === "let") {
        tokens.push(letToken(pos));
      } else if (word === "true" || word === "false") {
        tokens.push(boolToken(word === "true", pos));
      } else if (word === "if") {
        tokens.push(ifToken(pos));
      } else if (word === "then") {
        tokens.push(thenToken(pos));
      } else if (word === "else") {
        tokens.push(elseToken(pos));
      } else {
        tokens.push(identToken(word, pos));
      }
    } else if (ch === "=") {
      if (src.charAt(i + 1) === "=") {
        tokens.push(opToken("==", pos));
        i = i + 2;
      } else {
        tokens.push(equalsToken(pos));
        i = i + 1;
      }
    } else if (ch === ";") {
      tokens.push(semiToken(pos));
      i = i + 1;
    } else {
      return fail(`unexpected '${ch}'`, pos);
    }
  }
  tokens.push(eofToken({ line: line, col: i - lineStart + 1 }));
  return { ok: true, tokens: tokens };
}

type NumLit = { kind: "num"; value: number; pos: Pos };
type BoolLit = { kind: "bool"; value: boolean; pos: Pos };
type Var = { kind: "var"; name: string; pos: Pos };
type Neg = { kind: "neg"; operand: Expr; pos: Pos };
type If = { kind: "if"; cond: Expr; whenTrue: Expr; whenFalse: Expr; pos: Pos };
type Binary = { kind: "binary"; op: Op; left: Expr; right: Expr; pos: Pos };

type Expr = NumLit | BoolLit | Var | Neg | If | Binary;

function num(value: number, pos: Pos): NumLit {
  return { kind: "num", value: value, pos: pos };
}

function boolLit(value: boolean, pos: Pos): BoolLit {
  return { kind: "bool", value: value, pos: pos };
}

function variable(name: string, pos: Pos): Var {
  return { kind: "var", name: name, pos: pos };
}

function neg(operand: Expr, pos: Pos): Neg {
  return { kind: "neg", operand: operand, pos: pos };
}

function ifExpr(cond: Expr, whenTrue: Expr, whenFalse: Expr, pos: Pos): If {
  return { kind: "if", cond: cond, whenTrue: whenTrue, whenFalse: whenFalse, pos: pos };
}

function binary(op: Op, left: Expr, right: Expr, pos: Pos): Binary {
  return { kind: "binary", op: op, left: left, right: right, pos: pos };
}

type LetStmt = { kind: "let"; name: string; value: Expr };
type ExprStmt = { kind: "expr"; expr: Expr };

type Stmt = LetStmt | ExprStmt;

type Parser = { tokens: Token[]; pos: number };

function peek(p: Parser): Token {
  const t = p.tokens[p.pos];
  if (t === undefined) {
    throw new Error("peek past the end of the tokens");
  }
  return t;
}

function advance(p: Parser): Token {
  const t = peek(p);
  if (t.kind !== "eof") {
    p.pos = p.pos + 1;
  }
  return t;
}

function describe(t: Token): string {
  switch (t.kind) {
    case "number":
      return `'${t.value}'`;
    case "bool":
      return `'${t.value}'`;
    case "op":
      return `'${t.op}'`;
    case "ident":
      return `'${t.name}'`;
    case "let":
      return "'let'";
    case "equals":
      return "'='";
    case "semi":
      return "';'";
    case "if":
      return "'if'";
    case "then":
      return "'then'";
    case "else":
      return "'else'";
    case "lparen":
      return "'('";
    case "rparen":
      return "')'";
    case "eof":
      return "end of input";
    default:
      return assertNever(t);
  }
}

function unexpectedToken(t: Token): Failure {
  return fail(`unexpected ${describe(t)}`, t.pos);
}

function expected(what: string, t: Token): Failure {
  return fail(`expected ${what} but found ${describe(t)}`, t.pos);
}

type ParseResult = { ok: true; expr: Expr } | Failure;

function parseExpr(p: Parser): ParseResult {
  return parseComparison(p);
}

function parsePrimary(p: Parser): ParseResult {
  const t = advance(p);
  if (t.kind === "number") {
    return { ok: true, expr: num(t.value, t.pos) };
  }
  if (t.kind === "bool") {
    return { ok: true, expr: boolLit(t.value, t.pos) };
  }
  if (t.kind === "ident") {
    return { ok: true, expr: variable(t.name, t.pos) };
  }
  if (t.kind === "lparen") {
    const inner = parseExpr(p);
    if (!inner.ok) {
      return inner;
    }
    const close = advance(p);
    if (close.kind !== "rparen") {
      return expected("')'", close);
    }
    return inner;
  }
  if (t.kind === "if") {
    const cond = parseExpr(p);
    if (!cond.ok) {
      return cond;
    }
    const thenTok = advance(p);
    if (thenTok.kind !== "then") {
      return expected("'then'", thenTok);
    }
    const whenTrue = parseExpr(p);
    if (!whenTrue.ok) {
      return whenTrue;
    }
    const elseTok = advance(p);
    if (elseTok.kind !== "else") {
      return expected("'else'", elseTok);
    }
    const whenFalse = parseExpr(p);
    if (!whenFalse.ok) {
      return whenFalse;
    }
    return { ok: true, expr: ifExpr(cond.expr, whenTrue.expr, whenFalse.expr, t.pos) };
  }
  return unexpectedToken(t);
}

function parseUnary(p: Parser): ParseResult {
  const t = peek(p);
  if (t.kind === "op" && t.op === "-") {
    advance(p);
    const operand = parseUnary(p);
    if (!operand.ok) {
      return operand;
    }
    return { ok: true, expr: neg(operand.expr, t.pos) };
  }
  return parsePrimary(p);
}

function parseProduct(p: Parser): ParseResult {
  const first = parseUnary(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "*" || t.op === "/")) {
    advance(p);
    const right = parseUnary(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr, t.pos);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseSum(p: Parser): ParseResult {
  const first = parseProduct(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "+" || t.op === "-")) {
    advance(p);
    const right = parseProduct(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr, t.pos);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

function parseComparison(p: Parser): ParseResult {
  const first = parseSum(p);
  if (!first.ok) {
    return first;
  }
  let left = first.expr;
  let t = peek(p);
  while (t.kind === "op" && (t.op === "<" || t.op === ">" || t.op === "==")) {
    advance(p);
    const right = parseSum(p);
    if (!right.ok) {
      return right;
    }
    left = binary(t.op, left, right.expr, t.pos);
    t = peek(p);
  }
  return { ok: true, expr: left };
}

type StmtResult = { ok: true; stmt: Stmt } | Failure;

function parseStatement(p: Parser): StmtResult {
  if (peek(p).kind !== "let") {
    const e = parseExpr(p);
    if (!e.ok) {
      return e;
    }
    return { ok: true, stmt: { kind: "expr", expr: e.expr } };
  }
  advance(p);
  const name = advance(p);
  if (name.kind !== "ident") {
    return expected("a name", name);
  }
  const eq = advance(p);
  if (eq.kind !== "equals") {
    return expected("'='", eq);
  }
  const value = parseExpr(p);
  if (!value.ok) {
    return value;
  }
  return { ok: true, stmt: { kind: "let", name: name.name, value: value.expr } };
}

type ProgramResult = { ok: true; program: Stmt[] } | Failure;

function parseProgram(tokens: Token[]): ProgramResult {
  const p: Parser = { tokens: tokens, pos: 0 };
  const program: Stmt[] = [];
  while (true) {
    const s = parseStatement(p);
    if (!s.ok) {
      return s;
    }
    program.push(s.stmt);
    const t = advance(p);
    if (t.kind === "eof") {
      return { ok: true, program: program };
    }
    if (t.kind !== "semi") {
      return unexpectedToken(t);
    }
    if (peek(p).kind === "eof") {
      return { ok: true, program: program };
    }
  }
}

type Value = number | boolean;

type EvalResult = { ok: true; value: Value } | Failure;

function checked(value: number, pos: Pos): EvalResult {
  if (!Number.isFinite(value)) {
    return fail("number too large", pos);
  }
  return { ok: true, value: value };
}

type Env = Map<string, Value>;

function evaluate(e: Expr, env: Env): EvalResult {
  switch (e.kind) {
    case "num":
      return checked(e.value, e.pos);
    case "bool":
      return { ok: true, value: e.value };
    case "var": {
      const value = env.get(e.name);
      if (value === undefined) {
        return fail(`undefined variable '${e.name}'`, e.pos);
      }
      return { ok: true, value: value };
    }
    case "neg": {
      const operand = evaluate(e.operand, env);
      if (!operand.ok) {
        return operand;
      }
      if (typeof operand.value !== "number") {
        return fail("cannot apply '-' to a boolean", e.pos);
      }
      return { ok: true, value: -operand.value };
    }
    case "if": {
      const cond = evaluate(e.cond, env);
      if (!cond.ok) {
        return cond;
      }
      if (typeof cond.value !== "boolean") {
        return fail("if condition must be a boolean", e.pos);
      }
      if (cond.value) {
        return evaluate(e.whenTrue, env);
      }
      return evaluate(e.whenFalse, env);
    }
    case "binary": {
      const left = evaluate(e.left, env);
      if (!left.ok) {
        return left;
      }
      const right = evaluate(e.right, env);
      if (!right.ok) {
        return right;
      }
      return apply(e.op, left.value, right.value, e.pos);
    }
    default:
      return assertNever(e);
  }
}

function apply(op: Op, left: Value, right: Value, pos: Pos): EvalResult {
  if (op === "==") {
    if (typeof left !== typeof right) {
      return fail(`cannot compare a ${typeof left} with a ${typeof right}`, pos);
    }
    return { ok: true, value: left === right };
  }
  if (typeof left !== "number" || typeof right !== "number") {
    return fail(`cannot apply '${op}' to a boolean`, pos);
  }
  switch (op) {
    case "+":
      return checked(left + right, pos);
    case "-":
      return checked(left - right, pos);
    case "*":
      return checked(left * right, pos);
    case "/":
      if (right === 0) {
        return fail("division by zero", pos);
      }
      return checked(left / right, pos);
    case "<":
      return { ok: true, value: left < right };
    case ">":
      return { ok: true, value: left > right };
    default:
      return assertNever(op);
  }
}

function execute(s: Stmt, env: Env): EvalResult {
  switch (s.kind) {
    case "let": {
      const result = evaluate(s.value, env);
      if (!result.ok) {
        return result;
      }
      env.set(s.name, result.value);
      return result;
    }
    case "expr":
      return evaluate(s.expr, env);
    default:
      return assertNever(s);
  }
}

function runProgram(program: Stmt[], env: Env): EvalResult {
  let last: EvalResult = fail("empty program", { line: 1, col: 1 });
  for (const s of program) {
    last = execute(s, env);
    if (!last.ok) {
      return last;
    }
  }
  return last;
}

function lineOf(src: string, line: number): string {
  let start = 0;
  let n = 1;
  while (n < line) {
    start = src.indexOf("\n", start) + 1;
    n = n + 1;
  }
  let end = src.indexOf("\n", start);
  if (end === -1) {
    end = src.length;
  }
  return src.slice(start, end).trimEnd();
}

function report(src: string, err: CalcError): string {
  const caret = " ".repeat(err.pos.col - 1) + "^";
  return `${formatError(err)}\n  ${lineOf(src, err.pos.line)}\n  ${caret}`;
}

type Outcome = { text: string; code: number };

function run(src: string, env: Env): Outcome {
  const scanned = scan(src);
  if (!scanned.ok) {
    return { text: report(src, scanned.error), code: 1 };
  }
  const parsed = parseProgram(scanned.tokens);
  if (!parsed.ok) {
    return { text: report(src, parsed.error), code: 1 };
  }
  const result = runProgram(parsed.program, env);
  if (!result.ok) {
    return { text: report(src, result.error), code: 1 };
  }
  return { text: `${result.value}`, code: 0 };
}

function main(src: string, env: Env): Outcome {
  try {
    return run(src, env);
  } catch (e) {
    let detail = "unknown";
    if (e instanceof Error) {
      detail = e.message;
    }
    return { text: `error: internal error: ${detail}`, code: 2 };
  }
}

type Case = { src: string; want: string };

const CASES: Case[] = [
  { src: "1 + 2 * 3", want: "7" },
  { src: "(1 + 2) * -3", want: "-9" },
  { src: "10 / 4", want: "2.5" },
  { src: "let x = 4; x * x", want: "16" },
  { src: "x", want: "error: undefined variable 'x' at 1:1\n  x\n  ^" },
  { src: "let x = 4; x * x > 10", want: "true" },
  { src: "if 2 < 3 then 10 else 20", want: "10" },
  { src: "if false then 1 / 0 else 2", want: "2" },
  { src: "1 / 0", want: "error: division by zero at 1:3\n  1 / 0\n    ^" },
  { src: "1 + )", want: "error: unexpected ')' at 1:5\n  1 + )\n      ^" },
  { src: "y + 1", want: "error: undefined variable 'y' at 1:1\n  y + 1\n  ^" },
  { src: "true * 2", want: "error: cannot apply '*' to a boolean at 1:6\n  true * 2\n       ^" },
];

function check(c: Case): boolean {
  const got = main(c.src, new Map()).text;
  if (got === c.want) {
    return true;
  }
  const gotLines = got.split("\n");
  const wantLines = c.want.split("\n");
  let i = 0;
  while (i < gotLines.length && i < wantLines.length && gotLines[i] === wantLines[i]) {
    i = i + 1;
  }
  console.log(`FAIL ${c.src}`);
  console.log(`  line ${i + 1}`);
  console.log(`  want: ${JSON.stringify(wantLines[i])}`);
  console.log(`  got:  ${JSON.stringify(gotLines[i])}`);
  return false;
}

function repl(env: Env): void {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  rl.setPrompt("> ");
  rl.prompt();
  rl.on("line", (line) => {
    if (line.trim() !== "") {
      const outcome = main(line.trimEnd(), env);
      if (outcome.code === 0) {
        console.log(outcome.text);
      } else {
        console.error(outcome.text);
      }
    }
    rl.prompt();
  });
}

function runTests(): void {
  const results = CASES.map((c) => check(c));
  let passed = 0;
  for (const ok of results) {
    if (ok) {
      passed = passed + 1;
    }
  }
  console.log(`${passed} passed, ${results.length - passed} failed`);
  if (passed !== results.length) {
    process.exitCode = 1;
  }
}

if (process.argv[2] === "--test") {
  runTests();
} else if (process.stdin.isTTY) {
  repl(new Map());
} else {
  const outcome = main(readFileSync(0, "utf8").trimEnd(), new Map());
  if (outcome.code === 0) {
    console.log(outcome.text);
  } else {
    console.error(outcome.text);
  }
  process.exitCode = outcome.code;
}

